-- ============================================================
-- VERIFY – Kiểm tra số lượng records đã insert
-- ============================================================
SELECT 'users'             AS table_name, COUNT(*) AS total FROM users
UNION ALL SELECT 'doctors',           	 COUNT(*) FROM doctors
UNION ALL SELECT 'admission_staffs',     COUNT(*) FROM admission_staffs
UNION ALL SELECT 'patients',             COUNT(*) FROM patients
UNION ALL SELECT 'shifts',               COUNT(*) FROM shifts
UNION ALL SELECT 'working_times',        COUNT(*) FROM working_times
UNION ALL SELECT 'schedules',            COUNT(*) FROM schedules
UNION ALL SELECT 'appointments',         COUNT(*) FROM appointments
UNION ALL SELECT 'consultations',        COUNT(*) FROM consultations
UNION ALL SELECT 'diagnosis_results',    COUNT(*) FROM diagnosis_results
union all select 'diseases',		     COUNT(*) from diseases
union all select 'result_diseases',      COUNT(*) from result_diseases
union all select 'diagnose_models',      COUNT(*) from diagnose_models
union all select 'chatbots',             COUNT(*) from chatbots
union all select 'ai_diagnosis_results', COUNT(*) from ai_diagnosis_results
union all select 'ai_result_diseases',   COUNT(*) from ai_result_diseases
ORDER BY table_name;