INSERT INTO diagnosis_results (id, advices, prescription, description, symstoms_text, feed_back_ai, consultation_id, department, created_at, updated_at)
values
('2f42355f-3961-46e4-84ef-1031bd7e0a9b', 'Tránh va chạm mạnh gây chảy máu vùng tổn thương. Khi là chỉ khiến từ.', '[{"name": "Dung dịch làm mềm sừng", "dosage": "1 tuýp", "duration": "1 tháng"}, {"name": "Kháng sinh bôi nếu có loét", "dosage": "1 tuýp", "duration": "2 tuần"}]', 'Tổn thương mạch máu (U mạch, xuất huyết dưới da). - Thay rất như trong và tự.', 'Các đốm đỏ hoặc tím, phẳng hoặc gồ cao, không biến mất khi ấn vào. Tại đang để như như thế.', 'AI Suggest: VASC, Confidence: 85%.', 'af8c2cb6-f54e-4ddf-a24f-b254d63e7724', 'Dermatology', NOW(), NOW()),
('25aef4e3-2d4a-4f00-a325-8573a4eb5648', 'Hạn chế tiếp xúc ánh nắng mặt trời, sử dụng kem chống nắng phổ rộng hàng ngày. Từng nhưng của và.', '[{"name": "Dung dịch làm mềm sừng", "dosage": "1 viên/ngày", "duration": "1 tuần"}, {"name": "Kem dưỡng da chứa Urea", "dosage": "Bôi 2 lần/ngày", "duration": "1 tuần"}]', 'Dày sừng quang hóa, có dấu hiệu sừng hóa bề mặt. - Có mà cũng từng vậy.', 'Vảy thô, đỏ, khô trên da, thỉnh thoảng ngứa hoặc châm chích vùng tiếp xúc ánh nắng. Khiến từ chỉ để vài vẫn.', 'AI Suggest: AKIEC, Confidence: 97%.', '611b56c8-9934-4faf-a05d-1d186955955f', 'Dermatology', NOW(), NOW()),
('8d476d18-eae6-4b49-bb4a-1f8253bfa27a', 'Đây là tổn thương lành tính, có thể điều trị bằng áp lạnh nếu gây khó chịu về thẩm mỹ. Các có nào về được đang cái.', '[{"name": "Imiquimod 5%", "dosage": "1 viên/ngày", "duration": "2 tuần"}, {"name": "Pha loãng betadine vệ sinh", "dosage": "1 tuýp", "duration": "10 ngày"}]', 'Dày sừng tiết bã hoặc tổn thương dạng lichen. - Tôi số để dưới từng.', 'Mảng màu nâu hoặc đen, bề mặt thô ráp, trông giống như ''dán'' lên da. Nhưng vẫn đó với nào.', 'AI Suggest: BKL, Confidence: 95%.', '1c473fa2-f1de-4ae1-8c6d-3e0d249ee589', 'Dermatology', NOW(), NOW()),
('680fb1ef-e327-496e-9aca-8e2b5dc052e2', 'Hạn chế tiếp xúc ánh nắng mặt trời, sử dụng kem chống nắng phổ rộng hàng ngày. Người số được của.', '[{"name": "Kem 5-Fluorouracil", "dosage": "1 viên/ngày", "duration": "2 tuần"}, {"name": "Kem dưỡng da chứa Urea", "dosage": "1 tuýp", "duration": "1 tháng"}, {"name": "Kem chống nắng", "dosage": "Bôi 2 lần/ngày", "duration": "10 ngày"}]', 'Dày sừng quang hóa, có dấu hiệu sừng hóa bề mặt. - Thay giống nhiều như thì.', 'Vảy thô, đỏ, khô trên da, thỉnh thoảng ngứa hoặc châm chích vùng tiếp xúc ánh nắng. Của mỗi nếu vì cũng mà trong.', 'AI Suggest: AKIEC, Confidence: 89%.', '3f60d5cb-7c30-4dd0-80f6-97e64898734a', 'Dermatology', NOW(), NOW()),
('daa3d87f-d0e2-45ce-b1ff-84dedb9227ac', 'Đây là tổn thương lành tính, có thể điều trị bằng áp lạnh nếu gây khó chịu về thẩm mỹ. Các hơn về.', '[{"name": "Kem dưỡng ẩm phục hồi", "dosage": "1 tuýp", "duration": "10 ngày"}, {"name": "Diclofenac gel", "dosage": "Bôi 2 lần/ngày", "duration": "2 tuần"}]', 'Dày sừng tiết bã hoặc tổn thương dạng lichen. - Bạn số như đó không nào vì như.', 'Mảng màu nâu hoặc đen, bề mặt thô ráp, trông giống như ''dán'' lên da. Từ số dưới cách nào đi.', 'AI Suggest: BKL, Confidence: 88%.', '53c7e717-165a-4ca2-9067-79e627e7fc7d', 'Dermatology', NOW(), NOW()),
('32cdf5e0-9892-4655-a68d-18759eafdc04', 'Cần nhập viện phẫu thuật sớm nhất có thể. Kiểm tra hạch vùng. Chỉ như cũng bên.', '[{"name": "Kem chống nắng", "dosage": "Uống sau ăn", "duration": "2 tuần"}, {"name": "Dưỡng thể", "dosage": "1 viên/ngày", "duration": "1 tuần"}, {"name": "Kem dưỡng ẩm phục hồi", "dosage": "Uống sau ăn", "duration": "1 tuần"}]', 'Nghi ngờ u hắc tố ác tính (Melanoma). - Người các đã của một người cũng.', 'Nốt ruồi có hình dạng không đối xứng, bờ không đều, thay đổi màu sắc nhanh chóng. Nhưng đã nào.', 'AI Suggest: MEL, Confidence: 92%.', 'a35ee6a7-6795-4f2a-9d58-c636d8733dea', 'Dermatology', NOW(), NOW()),
('b084685c-3f14-4a56-b6fb-abc5aa792c47', 'Cần làm sinh thiết để xác định độ xâm lấn. Tránh gãi vùng tổn thương. Của cách vì về nơi từ giống.', '[{"name": "Vitamin C uống tăng bền mạch", "dosage": "1 tuýp", "duration": "1 tuần"}, {"name": "Dưỡng thể", "dosage": "Uống sau ăn", "duration": "1 tháng"}]', 'Nghi ngờ ung thư biểu mô tế bào đáy. - Thay tự chưa tự.', 'Sẩn bóng như ngọc trai, có mạch máu giãn trên bề mặt, thỉnh thoảng loét nhẹ. Thay không nơi chưa đi đến của.', 'AI Suggest: BCC, Confidence: 92%.', '9551da8e-0cb1-4a0e-b870-257205d3f57f', 'Dermatology', NOW(), NOW()),
('26f67e95-4cc4-4845-b9c5-35729cc8ef96', 'Tránh va chạm mạnh gây chảy máu vùng tổn thương. Làm là hơn cũng để sau chưa.', '[{"name": "Dung dịch làm mềm sừng", "dosage": "1 viên/ngày", "duration": "10 ngày"}, {"name": "Kem dưỡng ẩm phục hồi", "dosage": "Bôi 2 lần/ngày", "duration": "1 tuần"}]', 'Tổn thương mạch máu (U mạch, xuất huyết dưới da). - Trong đi và cho.', 'Các đốm đỏ hoặc tím, phẳng hoặc gồ cao, không biến mất khi ấn vào. Nếu của khiến nhưng tại gần khi chỉ.', 'AI Suggest: VASC, Confidence: 92%.', '3b6af389-34c4-419b-9023-8a9cc7509748', 'Dermatology', NOW(), NOW()),
('aa4877a1-b074-4c7e-b333-a6ab4ee8fca5', 'Hạn chế tiếp xúc ánh nắng mặt trời, sử dụng kem chống nắng phổ rộng hàng ngày. Sau có hoặc tại chỉ nhưng đã.', '[{"name": "Kem dưỡng da chứa Urea", "dosage": "Uống sau ăn", "duration": "1 tháng"}, {"name": "Kem chống nắng", "dosage": "1 tuýp", "duration": "1 tháng"}]', 'Dày sừng quang hóa, có dấu hiệu sừng hóa bề mặt. - Và bạn như để thì.', 'Vảy thô, đỏ, khô trên da, thỉnh thoảng ngứa hoặc châm chích vùng tiếp xúc ánh nắng. Nếu tại để giữa có đến dưới.', 'AI Suggest: AKIEC, Confidence: 91%.', 'e5b2fbf7-9198-45a0-b5f9-09523d4a11d4', 'Dermatology', NOW(), NOW()),
('1d1b9442-129f-4934-92c0-6e83897cde73', 'Tránh va chạm mạnh gây chảy máu vùng tổn thương. Để giống thế sẽ.', '[{"name": "Kem dưỡng ẩm phục hồi", "dosage": "Bôi 2 lần/ngày", "duration": "1 tuần"}, {"name": "Pha loãng betadine vệ sinh", "dosage": "1 tuýp", "duration": "1 tháng"}]', 'Tổn thương mạch máu (U mạch, xuất huyết dưới da). - Nơi thay đi cách từ.', 'Các đốm đỏ hoặc tím, phẳng hoặc gồ cao, không biến mất khi ấn vào. Cũng các để thì khi hơn tại.', 'AI Suggest: VASC, Confidence: 89%.', 'da531dff-aef7-43b2-8070-898e546141f8', 'Dermatology', NOW(), NOW()),
('99471016-842d-4b3a-aad3-3dc7708fb9bb', 'Không cần can thiệp trừ khi đau hoặc ngứa nhiều. Đang điều để này của trong làm.', '[{"name": "Giảm đau đường uống", "dosage": "1 viên/ngày", "duration": "1 tháng"}, {"name": "Diclofenac gel", "dosage": "Uống sau ăn", "duration": "1 tuần"}, {"name": "Pha loãng betadine vệ sinh", "dosage": "1 viên/ngày", "duration": "1 tuần"}]', 'U xơ da lành tính. - Đi gần nếu khi làm một.', 'Sẩn cứng, nhỏ, màu nâu hoặc hồng, thường xuất hiện ở chân, có dấu hiệu lúm đồng tiền khi bóp. Khiến có từng đến.', 'AI Suggest: DF, Confidence: 90%.', '4a012617-1231-4719-a9d0-2e38a7fb2ec1', 'Dermatology', NOW(), NOW()),
('5fadf7c0-10a5-4041-9c71-c7d3b8d070bf', 'Hạn chế tiếp xúc ánh nắng mặt trời, sử dụng kem chống nắng phổ rộng hàng ngày. Chưa cũng khi làm điều mà với.', '[{"name": "Imiquimod 5%", "dosage": "Bôi 2 lần/ngày", "duration": "10 ngày"}, {"name": "Dưỡng thể", "dosage": "Uống sau ăn", "duration": "1 tháng"}, {"name": "Kháng sinh bôi nếu có loét", "dosage": "Bôi 2 lần/ngày", "duration": "1 tuần"}]', 'Dày sừng quang hóa, có dấu hiệu sừng hóa bề mặt. - Số sau từ với.', 'Vảy thô, đỏ, khô trên da, thỉnh thoảng ngứa hoặc châm chích vùng tiếp xúc ánh nắng. Số bạn lớn từ của để.', 'AI Suggest: AKIEC, Confidence: 85%.', '23e03546-fb61-43bc-a1c9-0769bdd327df', 'Dermatology', NOW(), NOW()),
('a17f66ab-3820-40a6-b894-034dcfaaeee1', 'Cần làm sinh thiết để xác định độ xâm lấn. Tránh gãi vùng tổn thương. Đi như chỉ đi tại đó.', '[{"name": "Kem chứa Steroid nhẹ nếu ngứa", "dosage": "1 tuýp", "duration": "10 ngày"}, {"name": "Dung dịch làm mềm sừng", "dosage": "Uống sau ăn", "duration": "10 ngày"}]', 'Nghi ngờ ung thư biểu mô tế bào đáy. - Với của về khiến.', 'Sẩn bóng như ngọc trai, có mạch máu giãn trên bề mặt, thỉnh thoảng loét nhẹ. Và làm trong thay.', 'AI Suggest: BCC, Confidence: 95%.', '0fd2e3fd-36b9-47d4-8af3-1c3ea8572a0c', 'Dermatology', NOW(), NOW()),
('76bdbd02-5663-49d9-ba75-aa805f149bd1', 'Theo dõi định kỳ 6 tháng một lần theo quy tắc ABCDE. Chỉ thế mà tôi.', '[{"name": "Kem chứa Steroid nhẹ nếu ngứa", "dosage": "Uống sau ăn", "duration": "10 ngày"}, {"name": "Kem dưỡng da chứa Urea", "dosage": "1 tuýp", "duration": "1 tháng"}, {"name": "Dung dịch làm mềm sừng", "dosage": "Uống sau ăn", "duration": "1 tháng"}]', 'Nốt ruồi hắc tố lành tính. - Cho theo hoặc có.', 'Nốt ruồi có hình dạng tròn hoặc bầu dục đều đặn, màu sắc đồng nhất. Cái là vậy vì của để tại.', 'AI Suggest: NV, Confidence: 85%.', '776fd1b6-ac8d-4409-b148-9691cf7efdbc', 'Dermatology', NOW(), NOW()),
('d94ea705-a5e5-4353-bd21-29adcc738c64', 'Tránh va chạm mạnh gây chảy máu vùng tổn thương. Hơn mỗi về.', '[{"name": "Vitamin C uống tăng bền mạch", "dosage": "Uống sau ăn", "duration": "1 tháng"}, {"name": "Imiquimod 5%", "dosage": "Bôi 2 lần/ngày", "duration": "10 ngày"}]', 'Tổn thương mạch máu (U mạch, xuất huyết dưới da). - Làm nào nếu cái có với như nào.', 'Các đốm đỏ hoặc tím, phẳng hoặc gồ cao, không biến mất khi ấn vào. Và cái bên đúng nơi là.', 'AI Suggest: VASC, Confidence: 91%.', 'e2f330b9-ddfd-4e8a-aa51-a35202a69bfc', 'Dermatology', NOW(), NOW()),
('b0ef6f6a-61ba-4eb2-8b6d-a4cbcb997f85', 'Không cần can thiệp trừ khi đau hoặc ngứa nhiều. Không của như giống số có.', '[{"name": "Kem chống nắng", "dosage": "1 viên/ngày", "duration": "10 ngày"}, {"name": "Kháng sinh bôi nếu có loét", "dosage": "Uống sau ăn", "duration": "10 ngày"}]', 'U xơ da lành tính. - Cách cũng theo gần đến trong khi người.', 'Sẩn cứng, nhỏ, màu nâu hoặc hồng, thường xuất hiện ở chân, có dấu hiệu lúm đồng tiền khi bóp. Nào mà đã mỗi của.', 'AI Suggest: DF, Confidence: 99%.', '5db1a45d-41a2-4fe9-a5d5-27a48fffea49', 'Dermatology', NOW(), NOW()),
('bc370a52-165a-4d4c-96b1-0d4560b16122', 'Đây là tổn thương lành tính, có thể điều trị bằng áp lạnh nếu gây khó chịu về thẩm mỹ. Cũng đang bạn từ và.', '[{"name": "Kem chống nắng", "dosage": "1 viên/ngày", "duration": "1 tháng"}, {"name": "Kem dưỡng da chứa Urea", "dosage": "1 tuýp", "duration": "10 ngày"}, {"name": "Kem 5-Fluorouracil", "dosage": "Uống sau ăn", "duration": "2 tuần"}]', 'Dày sừng tiết bã hoặc tổn thương dạng lichen. - Như nếu sau giống vài.', 'Mảng màu nâu hoặc đen, bề mặt thô ráp, trông giống như ''dán'' lên da. Hơn chưa như đã của hơn khiến.', 'AI Suggest: BKL, Confidence: 95%.', '8fb6d9ed-d8d6-46fe-8ae0-8824006a11ff', 'Dermatology', NOW(), NOW()),
('2556e0ff-7709-43a0-96e6-45372ea75d10', 'Tránh va chạm mạnh gây chảy máu vùng tổn thương. Trong tôi với nếu để mỗi.', '[{"name": "Kem 5-Fluorouracil", "dosage": "1 tuýp", "duration": "10 ngày"}, {"name": "Giảm đau đường uống", "dosage": "Uống sau ăn", "duration": "1 tháng"}]', 'Tổn thương mạch máu (U mạch, xuất huyết dưới da). - Nhưng để mà vậy nếu.', 'Các đốm đỏ hoặc tím, phẳng hoặc gồ cao, không biến mất khi ấn vào. Khi với đến để để mà chỉ không.', 'AI Suggest: VASC, Confidence: 92%.', '13f14c44-0c1e-4dbe-be60-844abbb961c2', 'Dermatology', NOW(), NOW()),
('4735fa98-c095-4f65-94a0-48185af22e95', 'Không cần can thiệp trừ khi đau hoặc ngứa nhiều. Dưới này gần để tại tự cũng.', '[{"name": "Kem dưỡng da chứa Urea", "dosage": "Bôi 2 lần/ngày", "duration": "2 tuần"}, {"name": "Imiquimod 5%", "dosage": "1 viên/ngày", "duration": "10 ngày"}]', 'U xơ da lành tính. - Hơn nhưng thì.', 'Sẩn cứng, nhỏ, màu nâu hoặc hồng, thường xuất hiện ở chân, có dấu hiệu lúm đồng tiền khi bóp. Đã này không từ.', 'AI Suggest: DF, Confidence: 90%.', '2c66b204-5ab7-41db-9bf2-58f7810e7651', 'Dermatology', NOW(), NOW()),
('f59facda-9fc8-4b91-a9ba-85daaa1a0990', 'Cần nhập viện phẫu thuật sớm nhất có thể. Kiểm tra hạch vùng. Dưới đã để của vẫn đi của.', '[{"name": "Pha loãng betadine vệ sinh", "dosage": "1 viên/ngày", "duration": "2 tuần"}, {"name": "Dung dịch làm mềm sừng", "dosage": "Uống sau ăn", "duration": "10 ngày"}]', 'Nghi ngờ u hắc tố ác tính (Melanoma). - Mà với tự nhưng số nơi như.', 'Nốt ruồi có hình dạng không đối xứng, bờ không đều, thay đổi màu sắc nhanh chóng. Để đến có đang này cũng.', 'AI Suggest: MEL, Confidence: 98%.', '9f77d64f-2b05-44c9-859f-de1ef2526521', 'Dermatology', NOW(), NOW()),
('bd904561-b619-430c-9151-b1ad5a0353cb', 'Tránh va chạm mạnh gây chảy máu vùng tổn thương. Tôi có từ cũng có bên của.', '[{"name": "Dưỡng thể", "dosage": "Bôi 2 lần/ngày", "duration": "1 tháng"}, {"name": "Imiquimod 5%", "dosage": "Bôi 2 lần/ngày", "duration": "1 tuần"}]', 'Tổn thương mạch máu (U mạch, xuất huyết dưới da). - Đó dưới số được như tại.', 'Các đốm đỏ hoặc tím, phẳng hoặc gồ cao, không biến mất khi ấn vào. Từ cho là gần để.', 'AI Suggest: VASC, Confidence: 85%.', 'dac26f8c-73b4-42a8-b3de-d47817d93349', 'Dermatology', NOW(), NOW()),
('7f046973-6869-4acd-93f4-04760f8d6f31', 'Cần nhập viện phẫu thuật sớm nhất có thể. Kiểm tra hạch vùng. Với trong rất nơi.', '[{"name": "Dung dịch làm mềm sừng", "dosage": "1 viên/ngày", "duration": "10 ngày"}, {"name": "Vitamin C uống tăng bền mạch", "dosage": "Bôi 2 lần/ngày", "duration": "1 tháng"}]', 'Nghi ngờ u hắc tố ác tính (Melanoma). - Tự giữa lớn làm trong chưa người lớn.', 'Nốt ruồi có hình dạng không đối xứng, bờ không đều, thay đổi màu sắc nhanh chóng. Mỗi nếu được về như làm làm.', 'AI Suggest: MEL, Confidence: 99%.', '3da3dd16-3962-4f20-b3dc-a1c82377f99f', 'Dermatology', NOW(), NOW()),
