INSERT INTO ai_diagnosis_results (id, severity_level, ai_advice, proof, suggested_diagnosis, consultation_id, diagnose_model_id, created_at, updated_at) VALUES
('7635ab71-1fb4-4416-b748-4a932660f1c7', 'SEVERE', 'Tổn thương được xác định là u xơ da lành tính. Không cần can thiệp ngoại khoa trừ khi khối u gây đau hoặc cản trở sinh hoạt.', 'Vùng trung tâm tổn thương có màu trắng xám bao quanh bởi mạng lưới sắc tố mịn, phản ứng lúm đồng tiền xuất hiện khi có áp lực.', '[{"accuracy": 0.558100343, "diseaseName": "df"}, {"accuracy": 0.229716965, "diseaseName": "bcc"}, {"accuracy": 0.212082692, "diseaseName": "mel"}]', 'af8c2cb6-f54e-4ddf-a24f-b254d63e7724', 'd4fe184c-df08-4f59-b027-fb9c6f135e3e', NOW(), NOW()),
('62a8e2cb-e5a1-4020-836c-7fb8c0d22740', 'MODERATE', 'Tổn thương không nằm trong danh mục nhận diện chính. AI khuyến nghị bác sĩ thực hiện thêm các xét nghiệm cận lâm sàng khác.', 'Các đặc điểm lâm sàng không đủ đặc hiệu để đưa ra kết luận phân loại chính xác theo mô hình hiện tại.', '[{"accuracy": 0.593599678, "diseaseName": "others"}, {"accuracy": 0.36612035, "diseaseName": "akiec"}, {"accuracy": 0.040179972, "diseaseName": "vasc"}]', '611b56c8-9934-4faf-a05d-1d186955955f', '78fbef92-a439-4593-9a37-74b1178ddf9d', NOW(), NOW()),
('07c596f4-bdbc-4059-b58a-ebceb99b044e', 'MODERATE', 'Tổn thương không nằm trong danh mục nhận diện chính. AI khuyến nghị bác sĩ thực hiện thêm các xét nghiệm cận lâm sàng khác.', 'Các đặc điểm lâm sàng không đủ đặc hiệu để đưa ra kết luận phân loại chính xác theo mô hình hiện tại.', '[{"accuracy": 0.9999, "diseaseName": "others"}]', '1c473fa2-f1de-4ae1-8c6d-3e0d249ee589', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('93da7f56-4932-45f8-9117-0fc9b312bb7c', 'SEVERE', 'CẢNH BÁO: AI phát hiện cấu trúc nghi ngờ u hắc tố ác tính mức độ cao. Cần chuyển tuyến chuyên khoa khẩn cấp và thực hiện cắt rộng tổn thương.', 'Sự mất đối xứng nghiêm trọng về cấu trúc, mạng lưới sắc tố không điển hình và sự xuất hiện của các vệt màu xanh xám (blue-white veil).', '[{"accuracy": 0.648404244, "diseaseName": "mel"}, {"accuracy": 0.351495756, "diseaseName": "bkl"}]', '3f60d5cb-7c30-4dd0-80f6-97e64898734a', '12d5e9e1-b059-45a1-b0ed-03c3264cb4f2', NOW(), NOW()),
('84c89e33-adf5-42ee-8b18-9ecf41f8346e', 'MODERATE', 'Tổn thương mạch máu lành tính. Tránh các tác động vật lý mạnh gây chảy máu. Có thể sử dụng laser mạch máu nếu bệnh nhân muốn điều trị thẩm mỹ.', 'Sự hiện diện của các hốc mạch máu (lacunae) màu đỏ hoặc tím sẫm, không có mạng lưới sắc tố bao quanh.', '[{"accuracy": 0.995952732, "diseaseName": "vasc"}, {"accuracy": 0.003947268, "diseaseName": "akiec"}]', '53c7e717-165a-4ca2-9067-79e627e7fc7d', 'd4fe184c-df08-4f59-b027-fb9c6f135e3e', NOW(), NOW()),
('939a3f60-4b05-417e-ac62-cd06d0a18bc8', 'MODERATE', 'Đây là nốt ruồi hắc tố lành tính. AI khuyến nghị theo dõi định kỳ sau 6-12 tháng để đánh giá sự thay đổi về kích thước và màu sắc.', 'Cấu trúc sắc tố đồng nhất, ranh giới rõ ràng, không có các dấu hiệu loạn sản trên bề mặt da.', '[{"accuracy": 0.553909795, "diseaseName": "nv"}, {"accuracy": 0.445990205, "diseaseName": "others"}]', 'a35ee6a7-6795-4f2a-9d58-c636d8733dea', 'd4fe184c-df08-4f59-b027-fb9c6f135e3e', NOW(), NOW()),
('7ead1d33-9dd8-4be3-838a-2541af92d0b8', 'CRITICAL', 'Đây là nốt ruồi hắc tố lành tính. AI khuyến nghị theo dõi định kỳ sau 6-12 tháng để đánh giá sự thay đổi về kích thước và màu sắc.', 'Cấu trúc sắc tố đồng nhất, ranh giới rõ ràng, không có các dấu hiệu loạn sản trên bề mặt da.', '[{"accuracy": 0.391609943, "diseaseName": "nv"}, {"accuracy": 0.307092313, "diseaseName": "vasc"}, {"accuracy": 0.301197744, "diseaseName": "mel"}]', '9551da8e-0cb1-4a0e-b870-257205d3f57f', 'd4fe184c-df08-4f59-b027-fb9c6f135e3e', NOW(), NOW()),
('6e4eb87f-ab4d-481e-bcec-8705e27e09dc', 'MINOR', 'Tổn thương không nằm trong danh mục nhận diện chính. AI khuyến nghị bác sĩ thực hiện thêm các xét nghiệm cận lâm sàng khác.', 'Các đặc điểm lâm sàng không đủ đặc hiệu để đưa ra kết luận phân loại chính xác theo mô hình hiện tại.', '[{"accuracy": 0.9999, "diseaseName": "others"}]', '3b6af389-34c4-419b-9023-8a9cc7509748', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('237a5166-4c7f-4cf7-80e3-f02612d2da8f', 'MODERATE', 'Tổn thương được xác định là u xơ da lành tính. Không cần can thiệp ngoại khoa trừ khi khối u gây đau hoặc cản trở sinh hoạt.', 'Vùng trung tâm tổn thương có màu trắng xám bao quanh bởi mạng lưới sắc tố mịn, phản ứng lúm đồng tiền xuất hiện khi có áp lực.', '[{"accuracy": 0.9999, "diseaseName": "df"}]', 'e5b2fbf7-9198-45a0-b5f9-09523d4a11d4', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('7302b77b-62c6-4a2e-82de-e022bf4e9964', 'MINOR', 'Tổn thương mạch máu lành tính. Tránh các tác động vật lý mạnh gây chảy máu. Có thể sử dụng laser mạch máu nếu bệnh nhân muốn điều trị thẩm mỹ.', 'Sự hiện diện của các hốc mạch máu (lacunae) màu đỏ hoặc tím sẫm, không có mạng lưới sắc tố bao quanh.', '[{"accuracy": 0.415999047, "diseaseName": "vasc"}, {"accuracy": 0.373765421, "diseaseName": "bcc"}, {"accuracy": 0.210135532, "diseaseName": "others"}]', 'da531dff-aef7-43b2-8070-898e546141f8', 'd4fe184c-df08-4f59-b027-fb9c6f135e3e', NOW(), NOW()),
('df8e6f12-6c73-4dad-b5a6-510d63ec2a2d', 'SEVERE', 'Tổn thương được xác định là u xơ da lành tính. Không cần can thiệp ngoại khoa trừ khi khối u gây đau hoặc cản trở sinh hoạt.', 'Vùng trung tâm tổn thương có màu trắng xám bao quanh bởi mạng lưới sắc tố mịn, phản ứng lúm đồng tiền xuất hiện khi có áp lực.', '[{"accuracy": 0.9999, "diseaseName": "df"}]', '4a012617-1231-4719-a9d0-2e38a7fb2ec1', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('a9608bde-0910-4108-9e6a-f673dfd7a206', 'MODERATE', 'Tổn thương được xác định là u xơ da lành tính. Không cần can thiệp ngoại khoa trừ khi khối u gây đau hoặc cản trở sinh hoạt.', 'Vùng trung tâm tổn thương có màu trắng xám bao quanh bởi mạng lưới sắc tố mịn, phản ứng lúm đồng tiền xuất hiện khi có áp lực.', '[{"accuracy": 0.64661376, "diseaseName": "df"}, {"accuracy": 0.35328624, "diseaseName": "others"}]', '23e03546-fb61-43bc-a1c9-0769bdd327df', '12d5e9e1-b059-45a1-b0ed-03c3264cb4f2', NOW(), NOW()),
('2106ff82-e4c8-4f3d-8f60-dcd818948945', 'MODERATE', 'AI nhận diện đây là tổn thương lành tính. Bệnh nhân có thể chung sống hòa bình với tổn thương này nếu không có nhu cầu thẩm mỹ hoặc các triệu chứng kích ứng.', 'Hình ảnh soi da cho thấy cấu trúc dạng nang lông và các kẽ rãnh giống não, điển hình của dày sừng tiết bã.', '[{"accuracy": 0.865915959, "diseaseName": "bkl"}, {"accuracy": 0.133984041, "diseaseName": "bcc"}]', '0fd2e3fd-36b9-47d4-8af3-1c3ea8572a0c', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('3ad245dc-0595-41e7-8f38-ccc9dd61fba4', 'CRITICAL', 'CẢNH BÁO: AI phát hiện cấu trúc nghi ngờ u hắc tố ác tính mức độ cao. Cần chuyển tuyến chuyên khoa khẩn cấp và thực hiện cắt rộng tổn thương.', 'Sự mất đối xứng nghiêm trọng về cấu trúc, mạng lưới sắc tố không điển hình và sự xuất hiện của các vệt màu xanh xám (blue-white veil).', '[{"accuracy": 0.958511273, "diseaseName": "mel"}, {"accuracy": 0.041388727, "diseaseName": "others"}]', '776fd1b6-ac8d-4409-b148-9691cf7efdbc', 'd4fe184c-df08-4f59-b027-fb9c6f135e3e', NOW(), NOW()),
('6fff5905-3f23-4882-b78d-f8fe48f758d9', 'CRITICAL', 'AI nhận diện đây là tổn thương lành tính. Bệnh nhân có thể chung sống hòa bình với tổn thương này nếu không có nhu cầu thẩm mỹ hoặc các triệu chứng kích ứng.', 'Hình ảnh soi da cho thấy cấu trúc dạng nang lông và các kẽ rãnh giống não, điển hình của dày sừng tiết bã.', '[{"accuracy": 0.410553321, "diseaseName": "bkl"}, {"accuracy": 0.401716169, "diseaseName": "vasc"}, {"accuracy": 0.18763051, "diseaseName": "akiec"}]', 'e2f330b9-ddfd-4e8a-aa51-a35202a69bfc', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('9159dde5-74d0-40a4-bedc-43a09c77049c', 'SEVERE', 'Kết quả gợi ý ung thư biểu mô tế bào đáy. Đây là loại u ác tính tại chỗ, AI khuyến nghị bác sĩ nên chỉ định sinh thiết và lên phương án phẫu thuật cắt bỏ sớm.', 'Phát hiện các sẩn bóng mờ kèm theo mạng lưới mạch máu hình cành cây đặc trưng của tổn thương tế bào đáy.', '[{"accuracy": 0.50739915, "diseaseName": "bcc"}, {"accuracy": 0.342806156, "diseaseName": "vasc"}, {"accuracy": 0.149694694, "diseaseName": "akiec"}]', '5db1a45d-41a2-4fe9-a5d5-27a48fffea49', '78fbef92-a439-4593-9a37-74b1178ddf9d', NOW(), NOW()),
('7522857c-e63d-43ec-8128-4b9f00270194', 'MODERATE', 'Tổn thương mạch máu lành tính. Tránh các tác động vật lý mạnh gây chảy máu. Có thể sử dụng laser mạch máu nếu bệnh nhân muốn điều trị thẩm mỹ.', 'Sự hiện diện của các hốc mạch máu (lacunae) màu đỏ hoặc tím sẫm, không có mạng lưới sắc tố bao quanh.', '[{"accuracy": 0.632114665, "diseaseName": "vasc"}, {"accuracy": 0.367785335, "diseaseName": "nv"}]', '8fb6d9ed-d8d6-46fe-8ae0-8824006a11ff', 'c266e25c-a90e-43a2-ad25-91717063a399', NOW(), NOW()),
('02c1d7cb-2e42-41a6-a43c-fb9047eeeeb3', 'MINOR', 'AI phát hiện dấu hiệu của dày sừng quang hóa. Khuyên bệnh nhân nên tránh nắng tuyệt đối và sử dụng kem bôi điều trị theo chỉ định để ngăn ngừa tiến triển thành ung thư biểu mô tế bào vảy.', 'Phân tích hình ảnh cho thấy sự hiện diện của các mảng bong vảy không đều và cấu trúc sừng hóa bề mặt tập trung tại vùng da tiếp xúc ánh sáng.', '[{"accuracy": 0.857991978, "diseaseName": "akiec"}, {"accuracy": 0.141908022, "diseaseName": "nv"}]', '13f14c44-0c1e-4dbe-be60-844abbb961c2', '78fbef92-a439-4593-9a37-74b1178ddf9d', NOW(), NOW()),
